BEGIN;
CREATE TABLE standing_demand_authorizations (demand_id uuid NOT NULL,demand_version integer NOT NULL,automatic_renewal_permitted boolean NOT NULL,maximum_renewals integer NOT NULL CHECK(maximum_renewals>0),renewals_used integer NOT NULL DEFAULT 0 CHECK(renewals_used>=0),confirmed_at timestamptz NOT NULL,valid_until timestamptz NOT NULL,acceptance_digest text NOT NULL CHECK(acceptance_digest~'^[0-9a-f]{64}$'),PRIMARY KEY(demand_id,demand_version),CHECK(renewals_used<=maximum_renewals AND valid_until>confirmed_at));
CREATE TABLE recurring_candidates (id uuid PRIMARY KEY,relationship_id uuid NOT NULL REFERENCES protected_relationships(id),prior_fee_lock_id uuid NOT NULL REFERENCES fee_locks(id),offer_id uuid NOT NULL,offer_version integer NOT NULL,demand_id uuid NOT NULL,demand_version integer NOT NULL,status text NOT NULL CHECK(status='MATCHED_REQUIRES_NEW_FEE_LOCK'),created_at timestamptz NOT NULL,UNIQUE(relationship_id,offer_id,offer_version,demand_id,demand_version));
CREATE TABLE protected_purchase_observations (id uuid PRIMARY KEY,relationship_id uuid NOT NULL REFERENCES protected_relationships(id),supplier_id uuid NOT NULL,buyer_id uuid NOT NULL,commodity_family text NOT NULL,purchased_at timestamptz NOT NULL,direct_or_indirect text NOT NULL CHECK(direct_or_indirect IN('DIRECT','AFFILIATE','INDIRECT')),source_receipt_id uuid NOT NULL,qualifies boolean NOT NULL,created_at timestamptz NOT NULL);
INSERT INTO schema_migrations(version) VALUES('0022_recurring');COMMIT;
